function movementEvidence(name){return state.sessions.flatMap(x=>(x.items||[]).filter(y=>y.name===name).map(y=>({...y,date:x.date,effort:x.effort,notes:x.notes}))).slice(-8)}
function decision(item){const a=movementEvidence(item.name),last=a.at(-1),recent=a.slice(-2);if(!last)return {kind:'baseline',message:'Starting prescription: use a conservative load; establish clean, repeatable sets.'};const failures=recent.filter(x=>x.completed===false).length;if(failures>=2)return {kind:'reduce',message:'Two recent incomplete prescriptions: reduce the next demand; do not add weight.'};if(last.completed===false)return {kind:'hold',message:'Last exposure was incomplete: repeat or reduce the demand and review your notes.'};if(recent.length===2&&recent.every(x=>x.completed===true))return {kind:'progress',message:'Two consecutive successful exposures: consider a small rep increase before adding load.'};return {kind:'hold',message:'Build another successful exposure at this load before progressing.'}}
