function stepLoad(t,load,dir){const choices=availableLoads(t),increment=t.kind==='kb'?(Number(state.assessmentStep)===4?4:2):1;const target=load+dir*increment;return dir>0?choices.find(x=>x>=target)??null:[...choices].reverse().find(x=>x<=target)??null}
function recommendation(t,load,feel,reps){if(reps<t.reps||feel==='hard')return {action:'down',next:stepLoad(t,load,-1),message:'Reduce weight and retest. Stop immediately if technique breaks down.'};if(feel==='easy'){const next=stepLoad(t,load,1);return next?{action:'up',next,message:'Rest fully, then try the next weight. Stop when it is no longer easy.'}:{action:'save',next:load,message:'At the top of your available range; save only if technique stays controlled.'}}return {action:'save',next:load,message:'Use this as a provisional working weight; confirm it over all prescribed sets.'}}
function renderAssess(){const k=state.assessmentMode||'kb',a=assessState(k),tests=TESTS[k],t=tests[a.index];const last=state.assessments[k]?.date;return `<section class="hero"><p class="eyebrow">Weight setup</p><h2>Choose a useful training weight</h2><p>Two separate ~30-minute sessions: kettlebells and heavy club. No maximum attempts and no need to lift until failure.</p></section><div class="segmented"><button data-assess-mode="kb" class="${k==='kb'?'selected':''}">Kettlebells</button><button data-assess-mode="club" class="${k==='club'?'selected':''}">Heavy club</button></div><div class="note">Warm up first. Choose a familiar starting weight, perform one clean set, and report reps plus Easy / Right / Too hard. Easy means clearly repeatable with the same technique; Right means challenging but controlled and repeatable. Stop if painful, unstable, or technique changes. Rest ${k==='kb'?'2–3 minutes':'1–2 minutes'} between attempts. Keep each session around 30 minutes; resume later if needed.</div>${last?`<p class="muted">Last assessment: ${esc(last)}</p>`:''}${t?(()=>{const load=selectedLoad(t,a),reps=a.currentReps??t.reps,feel=a.currentFeel||'right',rec=recommendation(t,load,feel,Number(reps));return `<section class="card"><p class="eyebrow">Movement ${a.index+1} of ${tests.length}</p><h2>${esc(t.name)}</h2><div class="assessment-load">${load} ${k==='kb'?'kg':'lb'} ${t.bells?'per bell':''}</div><label class="field">Choose starting weight <select id="test-weight">${availableLoads(t).map(v=>`<option value="${v}" ${v===load?'selected':''}>${v} ${k==='kb'?'kg':'lb'}</option>`).join('')}</select></label>${k==='kb'?`<label class="field">Weight increase when easy <select id="test-step"><option value="2" ${Number(state.assessmentStep)!==4?'selected':''}>+2 kg (recommended)</option><option value="4" ${Number(state.assessmentStep)===4?'selected':''}>+4 kg (only if clearly easy)</option></select></label>`:''}<p><strong>Test ${t.reps} controlled reps${/Single-arm/.test(t.name)?' per side':''}</strong> · Rest ${t.rest} sec between attempts</p>${t.advanced?'<p class="warning"><strong>Optional advanced skill.</strong> Skip unless you already perform controlled snatches without pain. A clean test cannot establish snatch readiness.</p>':''}${guide({name:t.name})}<div class="assessment-inputs"><label>Reps completed<input id="test-reps" type="number" inputmode="numeric" min="0" max="${t.reps}" value="${esc(reps)}"></label><label>How did it feel?<select id="test-feel"><option value="easy" ${feel==='easy'?'selected':''}>Easy</option><option value="right" ${feel==='right'?'selected':''}>Right</option><option value="hard" ${feel==='hard'?'selected':''}>Too hard / form changed</option></select></label></div><p class="note" id="test-advice">${esc(rec.message)} ${rec.action==='save'?'Suggested weight: '+load+(k==='kb'?' kg':' lb'):rec.next?'Next attempt: '+rec.next+(k==='kb'?' kg':' lb'):'No lighter setting available; stop and adjust the exercise.'}</p><div class="flexbuttons"><button class="button" id="test-record">${rec.action==='save'?'Use this weight · Next movement':rec.next?'Try '+rec.next+(k==='kb'?' kg':' lb'):'Stop this test'}</button><button class="button outline" id="test-skip">Skip movement</button></div><p class="muted">This is a practical starting-weight check, not a validated prediction of strength. A successful single set must still be confirmed across your workout's full sets.</p></section>`})():`<section class="card"><h2>Assessment complete</h2><p>Prescribed weights can be edited below. Repeat in about four weeks, or sooner if training becomes too easy or too difficult.</p><button class="button" id="test-restart">Repeat this assessment</button></section>`}<section class="card"><h3>Working weights · auto-filled</h3><p class="muted">These are editable estimates, not additional assessment steps. Foundation tests provide conservative starting suggestions for related movements. A squat test does not prove a safe lunge or clean weight. Edit any weight here; completed or shortened workouts update the specific exercise’s next recommendation.</p>${[...new Map(PROGRAM.flatMap(w=>w.days.flatMap(d=>d.items)).filter(x=>usesLoad(x)&&unit(x)===(k==='kb'?'kg':'lb')).map(x=>[x.name,x])).values()].map(x=>`<label class="weight-setting">${esc(x.name)} <span><input type="number" min="0" max="${k==='kb'?32:17}" step="${k==='kb'?2:1}" inputmode="decimal" data-prescribe="${esc(x.name)}" value="${esc(state.weights[x.name]??suggestedWeight(x)??'')}" placeholder="Not set"> ${k==='kb'?'kg':'lb'}</span></label>`).join('')}</section>`}
function finishTest(kind,a,weight){const t=TESTS[kind][a.index];if(weight!=null)state.weights[t.id]=weight;a.index++;a.currentReps=null;a.currentFeel='right';if(a.index>=TESTS[kind].length)state.assessments[kind]={date:nowDate(),results:{...state.weights}};save();render()}
// V9: preparation is dynamic and specific to the day's demands; stretching follows training.
const WARMUP=[['Joint preparation','0–2 min','Easy shoulder, wrist, hip and ankle circles; stay in comfortable ranges.'],['Light pattern rehearsal','2–4 min','Unloaded hinge and squat, then a few light halos or club paths as appropriate.'],['Specific rehearsal','4–7 min','Rehearse the first loaded exercise with an easy weight, then the next movement pattern. Never rush heavy attempts.']];
const COOLDOWN=[['Settle breathing','0–2 min','Walk gently and breathe comfortably until breathing settles.'],['Hips and trunk','2–5 min','Choose easy hip flexor, posterior-chain or trunk mobility relevant to the session. No forced stretches.'],['Shoulders and finish','5–7 min','Easy shoulder and wrist mobility and relaxed breathing. Stop if uncomfortable.']];
const PREP={strength:WARMUP,club:WARMUP,technique:WARMUP,recovery:WARMUP};
const FINISH={strength:COOLDOWN,club:COOLDOWN,technique:COOLDOWN,recovery:COOLDOWN};
function estimateMainMinutes(day){
 // Conservative planning estimate, not a measured workout duration.
 return Math.ceil(day.items.reduce((sum,item)=>{
   const p=spec(item.target),rx=prescription(item);
   if(!p){const match=String(item.target).match(/(\d+)\s*(?:min|sec)/i);return sum+(match?(String(item.target).includes('sec')?Number(match[1])/60:Number(match[1])):4)}
   const reps=rx.sets*rx.reps*(p.sides||1);
   const work=reps*4/60;
   const rest=Math.max(0,rx.sets-1)*rx.rest/60;
   return sum+work+rest+1;
 },0));
}
function sessionKind(day){const t=day.type.toLowerCase();if(/mobility|easy club/.test(t))return 'recovery';if(/club/.test(t))return 'club';if(/technique|conditioning/.test(t))return 'technique';return 'strength'}
function routineBlock(label,rows,note){return `<section class="routine"><h3>${label}</h3><p class="muted">${note}</p><ol>${rows.map(([name,dose,how])=>`<li><strong>${esc(name)}</strong> <span>${esc(dose)}</span><div>${esc(how)}</div></li>`).join('')}</ol></section>`}
const ACTIVITY_TYPES=['Indoor cycling','Road cycling','Gravel cycling','Mountain biking','Hiking','Physical work / trail building','Walking','Other activity'];
function alternativePanel(){return `<section class="card activity-card"><h3>Replace today's workout</h3><p class="muted">Log what you did instead. This replaces the planned session for today's log; it does not pretend that cycling or physical work is equivalent to lifting.</p><label class="field">Activity <select id="activity-type">${ACTIVITY_TYPES.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><div class="activity-fields"><label>Minutes <input id="activity-minutes" type="number" min="1" max="1440" value="30"></label><label>Effort <select id="activity-effort"><option value="easy">Easy / recovery</option><option value="moderate" selected>Moderate</option><option value="hard">Hard</option></select></label></div><label class="field">Notes (optional) <textarea id="activity-notes" placeholder="Terrain, distance, elevation, work performed, how you felt"></textarea></label><button class="button" id="save-activity">Log replacement activity</button><button class="button outline" id="cancel-activity">Back to planned workout</button></section>`}
function feedbackOptions(value,choices){return choices.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${esc(label)}</option>`).join('')}
function renderTrain(){const n=position(),day=slotPlan(n),data=nextDraft(),kind=sessionKind(day),foundation=n<5;return `<section class="hero"><p class="eyebrow">${foundation?'Foundation session '+(n+1)+'/5':'Rotation '+(Math.floor((n-5)/ROTATION_LENGTH)+1)+' · session '+((n-5)%ROTATION_LENGTH+1)+'/3'}</p><h2>${esc(day.title)}</h2><p>${esc(day.focus)}</p></section><section class="card"><div class="row wrap"><strong>Today’s prescription</strong><span class="pill">7 / 31 / 7 · warm-up / practice / cooldown</span></div><p class="muted"><strong>45-minute ceiling:</strong> 7 min warm-up + up to 31 min main work + 7 min cooldown. Estimated main work: ${estimateMainMinutes(day)} min. ${estimateMainMinutes(day)>31?'This prescription may exceed the work block; reduce sets or rest only when technique and recovery permit.':'Allow extra time for transitions and stop the work block at 31 minutes.'} Never rush or skip rest to meet the clock.</p><button class="button secondary" id="replace-workout">Log a different activity</button>${state.showActivity?alternativePanel():`${routineBlock('Warm-up · 7 minutes',PREP[kind],'Progress from comfortable joint movement to specific rehearsal; keep the warm-up inside the session budget.')}<p class="muted">${foundation?'Foundation: each listed exercise is a measurable loaded baseline or confirmation. Mobility belongs in the warm-up and cooldown. A single successful exposure is provisional.':'Follow the prescription, then record what actually happened. Only controlled, repeatable work counts toward progression.'}</p>${day.items.map((item,i)=>{const e=data.items[i],p=spec(item.target),r=prescription(item),info=workInfo(item,e),options=usesLoad(item)?weightChoices(item,e.weight):[];return `<article class="exercise"><h3>${i+1}. ${esc(item.name)}</h3>${guide(item)}<p class="rx-rationale"><strong>${esc(r.kind.toUpperCase())} · ${foundation?'Find your working weight':'Your next step'}</strong><span class="rx-explain">${esc(foundation?'Begin at the suggested light weight. Complete the planned sets with clean technique, posture and breathing. If clearly too easy, carefully test the next available weight; if difficult, reduce. Record the final repeatable load. Never test to failure.':r.reason)}</span></p><p class="prescription-line"><strong>Prescribed:</strong> ${usesLoad(item)&&r.weight?`${bellCount(item)===2?'2 × ':''}${r.weight} ${unit(item)}`:'Unloaded'} · ${p?`${r.sets} sets × ${r.reps} reps${p.sides===2?' / side':''}`:esc(item.target)} · ${r.rest} sec rest</p><div class="editable-rx"><label>Weight (${unit(item)})${usesLoad(item)?`<select aria-label="Weight in ${unit(item)}" data-item="${i}" data-field="weight"><option value="">None</option>${options.map(x=>`<option value="${x}" ${Number(e.weight)===x?'selected':''}>${x}</option>`).join('')}</select>`:'<div class="no-weight">—</div>'}</label><label>Sets<input aria-label="Sets completed" type="number" min="0" max="50" data-item="${i}" data-field="setsDone" value="${esc(e.setsDone)}"></label><label>Reps${p?.sides===2?' / side':''}<input aria-label="Repetitions per set" type="number" min="0" max="100" data-item="${i}" data-field="repsDone" value="${esc(e.repsDone)}"></label><label>Rest (sec)<input aria-label="Rest in seconds" type="number" min="0" max="600" data-item="${i}" data-field="rest" value="${esc(e.rest)}"></label></div><div class="feedback-fields"><label>Difficulty<select data-item="${i}" data-field="quality">${feedbackOptions(e.quality||'unrated',[['unrated','Choose a response'],['easy','Too easy — could do substantially more'],['right','Appropriate — challenging but repeatable'],['hard','Too difficult — struggled to finish'],['incomplete','Unable to complete prescribed work'],['other','Other — explain']])}</select></label><label>Technique<select data-item="${i}" data-field="technique">${feedbackOptions(e.technique||'unrated',[['unrated','Choose a response'],['clean','Clean — controlled throughout'],['minor','Minor issues — occasional corrections'],['breakdown','Breakdown — lost control or form'],['other','Other — explain']])}</select></label><label class="technique-check"><input type="checkbox" data-item="${i}" data-field="pain" ${e.pain===true?'checked':''}> Pain or unusual discomfort occurred</label>${e.quality==='other'||e.technique==='other'||e.pain===true?`<label>Additional details<textarea data-item="${i}" data-field="note" placeholder="What happened?">${esc(e.note||'')}</textarea></label>`:''}<details class="training-detail"><summary>Uneven sets (optional)</summary><label>Reps by set, comma-separated<input data-item="${i}" data-field="actualSets" type="text" value="${esc(Array.isArray(e.actualSets)?e.actualSets.join(','):e.actualSets||'')}" placeholder="6, 6, 4"></label></details></div></article>`}).join('')}${routineBlock('Cooldown · 7 minutes',FINISH[kind],'Gentle movement and breathing; no forced positions. Finish within the session budget.')}`}</div><label class="field">Date <input id="date" type="date" value="${esc(data.date)}"></label><label class="field">Session notes (optional) <textarea id="notes" placeholder="Only if something important is not captured by exercise feedback">${esc(data.notes)}</textarea></label><div class="flexbuttons"><button class="button" id="complete">Save workout & update report</button><button class="button secondary" id="reset-draft">Reset draft</button></div><p class="status">Drafts save locally while you edit. Saving records each exercise by date and updates its progression assessment.</p></section>`}

function movementCatalog(){
 const items=new Map();
 const add=(name,type,dose='',how='')=>{const key=name.trim().toLowerCase();if(!items.has(key))items.set(key,{name:name.trim(),type,dose,how})};
 PROGRAM.forEach(w=>w.days.forEach(d=>d.items.forEach(i=>add(i.name,/club|cast|circle|front swing|flow/i.test(i.name)?'club':'kb'))));
 for(const [kind,rows] of Object.entries(PREP))for(const [name,dose,how] of rows)add(name,'warmup',dose,how);
 for(const [kind,rows] of Object.entries(FINISH))for(const [name,dose,how] of rows)add(name,'cooldown',dose,how);
 for(const group of Object.values(TESTS))for(const t of group)add(t.name,t.kind==='club'?'club':'kb');
 return [...items.values()].sort((a,b)=>a.name.localeCompare(b.name));
}
function renderMovementCatalog(){const q=movementQuery.toLowerCase(),f=movementFilter;const all=movementCatalog(),list=all.filter(x=>(f==='all'||x.type===f)&&x.name.toLowerCase().includes(q));
 return `<section class="card"><h2>Learn the movements</h2><p class="muted">Every workout movement, warm-up and cool-down, alphabetically. Review technique before adding load. Video searches need internet; check the exact variation and demonstrator.</p><label class="field">Find a movement<input id="movement-search" type="search" placeholder="Search by movement name" value="${esc(movementQuery)}"></label><div class="filter-row">${[['all','All'],['kb','Kettlebell'],['club','Club'],['warmup','Warm-up'],['cooldown','Cool-down']].map(([v,t])=>`<button class="filter-button ${f===v?'selected':''}" data-movement-filter="${v}">${t}</button>`).join('')}</div><div class="movement-results">${list.map((x,i)=>{const letter=x.name[0].toUpperCase(),previous=list[i-1]?.name[0].toUpperCase();return `${letter!==previous?`<h3 class="letter">${esc(letter)}</h3>`:''}<details class="movement-entry"><summary><span>${esc(x.name)}</span><small>${x.type==='kb'?'KB':x.type==='club'?'Club':x.type==='warmup'?'Warm-up':'Cool-down'}</small></summary>${x.dose?`<p><strong>Suggested dose:</strong> ${esc(x.dose)}</p>`:''}${x.how?`<p><strong>Purpose:</strong> ${esc(x.how)}</p>`:''}${x.type==='warmup'||x.type==='cooldown'?`<div class="setup-cue"><strong>Setup:</strong> ${esc(x.how)}</div><div class="movement-cue"><strong>Practice:</strong> Move slowly and comfortably for ${esc(x.dose)}. Keep breathing relaxed; stop if painful.</div><div class="video-slot"><button class="button secondary" data-search-video="${esc(x.name)}">Video pending verification</button></div>`:guide({name:x.name})}</details>`}).join('')||'<p class="muted">No movements match this search.</p>'}</div></section>`;
}
function renderHub(){return `<section class="hero"><p class="eyebrow">Training hub</p><h2>Learn. Assess. Progress.</h2><p>Find working weights, practice movements and review your prescriptions.</p></section><div class="hub-tabs"><button class="${hubSection==='weights'?'selected':''}" data-hub-section="weights">Weight setup</button><button class="${hubSection==='learn'?'selected':''}" data-hub-section="learn">Learn movements</button></div>${hubSection==='weights'?renderAssess():renderMovementCatalog()}`}
function logDate(value){const m=/^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(value||''));if(!m)return esc(value||'Date not recorded');const d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));return Number.isNaN(d.getTime())?esc(value):esc(new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(d))}
function renderHistory(){const sessions=[...state.sessions].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));return `${renderIntelligence()}<section class="card training-log-card"><div class="log-title-row"><div><p class="eyebrow">Your training notebook</p><h2>Workouts by date</h2><p class="muted">Open any date for the exercise-by-exercise record, just like a paper training notebook.</p></div></div><div class="log-list">${sessions.length?sessions.map(s=>`<details class="log-session"><summary><span class="log-session-main"><time class="log-date" datetime="${esc(s.date||'')}">${logDate(s.date)}</time><strong class="log-session-title">${esc(s.title||'Training session')}</strong><span class="log-session-meta">${esc(s.activity?.type||s.type||'Workout')}</span></span><span class="log-expand" aria-hidden="true">⌄</span></summary><div class="log-inner">${s.activity?`<p>${esc(s.activity.type)} · ${esc(s.activity.minutes)} min · ${esc(s.activity.effort)}</p>`:`<div class="notebook-scroll"><table class="notebook-table"><thead><tr><th>Exercise</th><th>Weight</th><th>Work</th><th>Rest</th><th>Result</th></tr></thead><tbody>${(s.items||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.weight||'—')} ${esc(x.unit||'')}</td><td>${esc(x.setsDone??x.sets)} × ${esc(x.actualReps??x.reps)}</td><td>${esc(x.rest??'—')}s</td><td>${esc(outcome(x))}</td></tr>${x.note?`<tr><td colspan="5" class="notebook-note">${esc(x.name)}: ${esc(x.note)}</td></tr>`:''}`).join('')}</tbody></table></div>`}${s.notes?`<p class="note">Session note: ${esc(s.notes)}</p>`:''}<button class="button secondary" data-delete="${esc(s.id)}">Delete this entry</button></div></details>`).join(''):'<p class="log-empty">No workouts yet. Your first Foundation workout will start the notebook.</p>'}</div></section>`}

function renderSettings(){return `<section class="card"><h3>Data protection</h3><p><strong>Local autosave:</strong> enabled. All changes are saved on this device.</p><p><strong>Off-device automatic backup:</strong> not connected. Do not rely on this app alone if your phone is lost.</p><p class="muted">Automatic private GitHub sync requires a secure authorization service; no token is embedded in this public app. Use full JSON export until a secure service is configured.</p></section><section class="hero"><p class="eyebrow">Your data</p><h2>Local, private, yours.</h2><p>No account, tracking, or server database. Your workouts are saved on this device. Cloud backup is not configured.</p></section><section class="card stack"><h3>Back up your training</h3><p class="muted">Export JSON to restore every workout and saved draft. Export CSV to analyze completed workouts in Google Sheets or Excel.</p><button class="button" id="export-json">Download full backup (.json)</button><button class="button secondary" id="export-csv">Download workout history (.csv)</button><div class="field"><label for="import-json">Restore from a JSON backup</label><input id="import-json" type="file" accept="application/json,.json"></div><p class="warning">Local storage can disappear if you clear browser data, uninstall the app, or lose your phone. Save a backup regularly. Restoring replaces the current local history.</p></section><section class="card"><h3>Start fresh</h3><p class="muted">Erase local workout history, saved drafts and assessed weights on this device. This cannot be undone without a backup.</p><button class="button secondary" id="reset-all-data">Reset all training data</button></section><section class="card"><h3>About your plan</h3><p class="muted">Three-session rolling rotation combining kettlebell and heavy-club movements. Train on any day; the next session advances only when a workout is saved.</p><p class="muted">Exercises are a starting template, not individualized medical advice. Gradually increase loading only when technique stays solid. Scale back anything that irritates the Achilles or shoulders.</p></section>`}
let libraryIndex=[],libraryQuery='',libraryGroup='All',libraryReady=false;
async function loadLibrary(){
 if(libraryReady)return;
 try{const r=await fetch('./legacy/source-index.json');if(!r.ok)throw Error('index unavailable');libraryIndex=await r.json();libraryReady=true;if(view==='library')render()}
 catch(e){console.warn('Source index unavailable',e)}
}
function renderLibrary(){
 const groups=['All','Nerd Math','Kettlebell','Heavy Club','Warmup & Mobility','Training Principles','Other'];
 const q=libraryQuery.toLowerCase().trim();
 const matching=libraryIndex.filter(x=>(libraryGroup==='All'||x.group===libraryGroup)&&(!q||x.title.toLowerCase().includes(q)));
 return `<section class="hero"><p class="eyebrow">Wildman research library</p><h2>720-source atlas</h2><p>Browse the complete source inventory by training subject. This is a research index, not yet a validated synthesis of every lesson.</p></section><section class="card"><div class="library-stats"><strong>${libraryIndex.length||'…'} indexed lessons</strong><span>Offline searchable · source titles</span></div><label class="field">Find a subject or movement<input id="library-search" type="search" value="${esc(libraryQuery)}" placeholder="e.g. snatch, density, club"></label><div class="library-filters">${groups.map(g=>`<button type="button" class="button ${libraryGroup===g?'':'secondary'}" data-library-group="${esc(g)}">${esc(g)}</button>`).join('')}</div><p class="muted">${matching.length} matching lessons · classifications are provisional and based on titles.</p><div class="library-results">${matching.slice(0,100).map(x=>`<article class="library-result"><strong>${esc(x.title)}</strong><div class="muted">${esc(x.group)} · ${x.words.toLocaleString()} transcript words</div></article>`).join('')}</div>${matching.length>100?'<p class="muted">Showing the first 100 results. Narrow your search to see more.</p>':''}</section>`;
}
function render(){document.body.dataset.page=view;const heads={plan:['Program','Your rolling training plan'],train:['Workout','Kettlebell / Heavy Club'],hub:['Learn','Movement guide / Weight setup'],history:['Log','Your work over time'],settings:['Settings','Make it yours'],library:['Atlas','Source inventory']};const h=heads[view]||heads.train;document.getElementById('page-heading').innerHTML=h[0];document.getElementById('page-tagline').textContent=h[1];document.getElementById('view').innerHTML=view==='plan'?renderPlan():view==='train'?renderTrain():view==='hub'?renderHub():view==='history'?renderHistory():view==='library'?renderLibrary():renderSettings();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view)});mountClock();updateTimer()}
function download(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
const csv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
function csvData(){const rows=[['Date','Workout','Exercise','Weight','Unit','Sets completed','Reps per set','Rest seconds','Difficulty','Technique','Pain','Completed','Notes']];for(const s of state.sessions)for(const x of s.items||[])rows.push([s.date,s.title,x.name,x.weight,x.unit,x.setsDone,x.actualReps,x.rest,x.quality,x.technique,x.pain?'Yes':'No',x.completed?'Yes':'No',x.note||'']);return rows.map(r=>r.map(csv).join(',')).join('\r\n')}

function confirmDialog(title,message,onYes){const dlg=document.getElementById('dialog');dlg.querySelector('form').innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="flexbuttons"><button class="button danger" value="yes">Yes, continue</button><button class="button outline" value="cancel">Cancel</button></div>`;dlg.showModal();dlg.addEventListener('close',function done(){dlg.removeEventListener('close',done);if(dlg.returnValue==='yes')onYes()})}
function parseBackup(input){if(!input||input.version!==1||!Array.isArray(input.sessions)||!input.drafts||typeof input.drafts!=='object'||Array.isArray(input.drafts))throw Error('Not a compatible Strength Lab backup');for(const s of input.sessions){if(!s||!Number.isInteger(s.week)||s.week<0||s.week>10000||!Number.isInteger(s.day)||s.day<0||s.day>4||!Array.isArray(s.items)||typeof s.date!=='string'||typeof s.id!=='string')throw Error('Backup contains an invalid workout')}return {...initial(),...input,sessions:input.sessions,drafts:input.drafts,weights:input.weights||{},assessments:input.assessments||{},assessmentDraft:input.assessmentDraft||{},sequence:Number.isInteger(input.sequence)?input.sequence:input.sessions.filter(s=>!s.activity).length,selectedWeek:0,selectedDay:0}}
document.addEventListener('change',e=>{const el=e.target;if(el.matches('input[type="checkbox"][data-field="pain"]')){const d=nextDraft(),i=Number(el.dataset.item);if(d.items[i]){d.items[i].pain=el.checked;save();render()}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if('view'in b.dataset){view=b.dataset.view;render();if(view==='library')loadLibrary();return}if('libraryGroup'in b.dataset){libraryGroup=b.dataset.libraryGroup;render();return}if('assessTab'in b.dataset){view='hub';hubSection='weights';render();return}if('hubSection'in b.dataset){hubSection=b.dataset.hubSection;render();return}if('movementFilter'in b.dataset){movementFilter=b.dataset.movementFilter;render();return}if('week'in b.dataset){state.showActivity=false;assessmentTab=false;state.selectedWeek=Number(b.dataset.week);save();render();return}if('day'in b.dataset){state.showActivity=false;assessmentTab=false;state.selectedDay=Number(b.dataset.day);save();render();return}if('assessBack'in b.dataset){view='train';render();return}if('assessMode'in b.dataset){state.assessmentMode=b.dataset.assessMode;save();render();return}if('playVideo'in b.dataset){const slot=b.closest('.video-slot');if(b.dataset.playVideo&&navigator.onLine){slot.innerHTML='<iframe title="Mark Wildman technique video" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(b.dataset.playVideo)+'"></iframe>'}else if(navigator.onLine){alert('A verified direct instructional video is not yet available for this movement. Use the written guide.')}else alert('Videos require an internet connection. Use the written technique instructions.');return}switch(b.id){case 'go-next':view='train';render();return;case 'replace-workout':state.showActivity=!state.showActivity;render();return;case 'cancel-activity':state.showActivity=false;render();return;case 'save-activity':{const type=document.getElementById('activity-type')?.value,minutes=Number(document.getElementById('activity-minutes')?.value),effort=document.getElementById('activity-effort')?.value,notes=document.getElementById('activity-notes')?.value||'';if(!ACTIVITY_TYPES.includes(type)||!Number.isInteger(minutes)||minutes<1||minutes>1440){alert('Select an activity and enter a valid duration.');return}const n=position(),w=n<5?0:1,d=n<5?n:(n-5)%ROTATION_LENGTH,day=slotPlan(n),dd=nextDraft();state.sessions.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),date:dd.date||nowDate(),week:w,day:d,title:'Alternative: '+type,type:'Alternative activity',activity:{type,minutes,effort},items:[],notes,createdAt:new Date().toISOString()});state.showActivity=false;if(save()){view='history';render()}return}case 'test-record':{const k=state.assessmentMode||'kb',a=assessState(k),t=TESTS[k][a.index],load=selectedLoad(t,a),reps=Number(a.currentReps??t.reps),feel=a.currentFeel||'right';if(!Number.isInteger(reps)||reps<0||reps>t.reps){alert('Enter a valid number of reps.');return}const rec=recommendation(t,load,feel,reps);a.attempts.push({name:t.name,load,reps,feel,date:nowDate()});if(rec.action==='save')finishTest(k,a,load);else if(rec.next){a.loads[t.id]=rec.next;a.currentReps=t.reps;a.currentFeel='right';save();render()}else{save();alert('No lighter weight available. Stop this test and use an easier variation.')}return}case 'test-skip':{const k=state.assessmentMode||'kb',a=assessState(k);finishTest(k,a,null);return}case 'test-restart':{const k=state.assessmentMode||'kb';state.assessmentDraft[k]={index:0,round:0,loads:{},attempts:[],date:nowDate()};save();render();return}case 'complete':{const d=nextDraft();if(!state.showActivity&&d.items.some(x=>!['right','easy','hard','incomplete','other'].includes(x.quality)||!['clean','minor','breakdown','other'].includes(x.technique))){alert('Rate movement quality for every exercise before saving. Unrated work cannot establish readiness.');return}const n=position(),day=slotPlan(n),dd=nextDraft();if(!dd.date){alert('Select a date');return}const items=day.items.map((item,i)=>{const e=dd.items[i],r=prescription(item),p=spec(item.target),raw=Array.isArray(e.actualSets)?e.actualSets.join(','):String(e.actualSets||''),actualSets=raw.split(',').filter(v=>v.trim()!=='').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v)&&v>=0&&v<=100),setsDone=actualSets.length||numeric(e.setsDone),repsDone=actualSets.length?Math.min(...actualSets):numeric(e.repsDone),targetSets=r.sets||p?.sets||0,targetReps=r.reps||p?.reps||0,completed=p?setsDone>=targetSets&&repsDone>=targetReps&&['right','easy'].includes(e.quality)&&e.technique==='clean'&&!e.pain:null,volume=numeric(e.weight)*bellCount(item)*(actualSets.length?actualSets.reduce((a,b)=>a+b,0):setsDone*repsDone)*(p?.sides||1);return {name:item.name,weight:e.weight,unit:unit(item),sets:String(setsDone),reps:String(repsDone),setsDone,actualReps:repsDone,actualSets,plannedSets:targetSets,targetReps,rest:numeric(e.rest),quality:e.pain?'pain':e.quality||'unrated',technique:e.technique||'unrated',pain:e.pain===true,techniqueConfirmed:e.technique==='clean'&&!e.pain,effort:dd.effort||'',prescribedRest:r.rest,prescribedWeight:r.weight,prescribedUnit:unit(item),note:e.note||'',completed,volume:Number.isFinite(volume)?volume:null,reason:r.reason}});state.sessions.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),date:dd.date,week:n<5?0:1,day:n<5?n:(n-5)%ROTATION_LENGTH,title:day.title,type:day.type,items,notes:dd.notes,effort:dd.effort,createdAt:new Date().toISOString()});delete state.drafts[draftKey(n)];state.sequence=n+1;items.forEach(x=>{if(verified(x)&&numeric(x.weight)>0)state.weights[x.name]=numeric(x.weight)});if(save()){view='history';render()}return}case 'reset-draft':confirmDialog('Reset this draft?','Clear unsaved workout entries for this day?',()=>{delete state.drafts[draftKey(position())];save();render()});return;case 'reset-all-data':confirmDialog('Erase all training data?','This permanently clears local workouts, drafts and working weights on this device. Export a backup first if you need one.',()=>{state=initial();save();view='train';render()});return;case 'export-json':download('strength-lab-backup-'+nowDate()+'.json',JSON.stringify(state,null,2),'application/json');return;case 'export-csv':download('strength-lab-history-'+nowDate()+'.csv','\ufeff'+csvData(),'text/csv;charset=utf-8');return;case 'timer-toggle':startClock();return;case 'timer-reset':resetClock();return;case 'clock-options':{const el=document.getElementById('clock-settings');el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden));return}}if('useLast'in b.dataset){const i=Number(b.dataset.useLast),dd=ensureDraft(state.selectedWeek,state.selectedDay);dd.items[i].weight=recentWeight(PROGRAM[state.selectedWeek].days[state.selectedDay].items[i].name);save();render();return}if('delete'in b.dataset){const id=b.dataset.delete;confirmDialog('Delete workout?','This removes the session from your local history. Export a backup first if needed.',()=>{state.sessions=state.sessions.filter(s=>s.id!==id);save();render()})}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='library-search'){libraryQuery=el.value;const cursor=el.selectionStart;render();const f=document.getElementById('library-search');if(f){f.focus();f.setSelectionRange(cursor,cursor)}return}if(el.id==='test-reps'){const a=assessState(state.assessmentMode||'kb');a.currentReps=el.value;save();return}if(el.id.startsWith('clock-')&&el.type==='number'){const prop=el.id.slice(6);if(['work','rest','minute','rounds'].includes(prop)){clock[prop]=Math.max(1,Math.min(600,Number(el.value)||1));resetClock()}return}if('prescribe'in el.dataset){const n=Number(el.value);if(el.value===''||!Number.isFinite(n)||n<=0)delete state.weights[el.dataset.prescribe];else state.weights[el.dataset.prescribe]=n;save();return}if(el.id==='movement-search'){movementQuery=el.value;const selectionStart=el.selectionStart;render();const newInput=document.getElementById('movement-search');if(newInput){newInput.focus();newInput.setSelectionRange(selectionStart,selectionStart)}return}if(view!=='train')return;const dd=nextDraft();if('item'in el.dataset){const i=Number(el.dataset.item);if(dd.items[i]&&['weight','setsDone','repsDone','rest','quality','technique','note','actualSets'].includes(el.dataset.field)){dd.items[i][el.dataset.field]=el.value;if(['quality','technique'].includes(el.dataset.field)){save();render();return}const node=document.querySelector('[data-capacity="'+i+'"]');if(node){const item=slotPlan(position()).items[i],info=workInfo(item,dd.items[i]);node.textContent=info.countable?'Work volume: '+(info.volume===null?'—':info.volume.toLocaleString())+' '+info.unit:'Timed or ladder movement · volume not estimated'}}}else if(['notes','date','effort'].includes(el.id)){dd[el.id]=el.value}else return;save()});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='library-search'){libraryQuery=el.value;const cursor=el.selectionStart;render();const f=document.getElementById('library-search');if(f){f.focus();f.setSelectionRange(cursor,cursor)}return}if(el.id==='test-reps'){render();return}if(el.dataset.field==='weight'&&view==='train'&&!assessmentTab){const dd=nextDraft();dd.items[Number(el.dataset.item)].weight=el.value;save();const node=document.querySelector('[data-capacity=\"'+el.dataset.item+'\"]');if(node){const info=workInfo(slotPlan(position()).items[Number(el.dataset.item)],dd.items[Number(el.dataset.item)]);node.textContent=info.countable?'Work volume: '+(info.volume===null?'—':info.volume.toLocaleString())+' '+info.unit:'Timed or ladder movement · volume not estimated'}return}if(el.id==='test-step'){state.assessmentStep=Number(el.value);save();render();return}if(el.id==='test-weight'){const k=state.assessmentMode||'kb',a=assessState(k),t=TESTS[k][a.index];a.loads[t.id]=Number(el.value);save();render();return}if(el.id==='test-feel'){const a=assessState(state.assessmentMode||'kb');a.currentFeel=el.value;save();render();return}if(el.id==='clock-mode'){clock.mode=el.value;if(clock.mode==='interval'){clock.work=40;clock.rest=20;document.getElementById('clock-work').value=40;document.getElementById('clock-rest').value=20}else if(clock.mode==='rest'){clock.rest=90;document.getElementById('clock-rest').value=90}resetClock();syncClockSettings();return}if(el.id==='clock-beeps'){clock.beeps=el.checked;return}if(el.id==='clock-lead'){clock.lead=Number(el.value);resetClock();return}if(el.id==='effort'&&view==='train'){nextDraft().effort=el.value;save()}if(el.id!=='import-json'||!el.files?.[0])return;try{if(el.files[0].size>5_000_000)throw Error('Backup is too large');const candidate=parseBackup(JSON.parse(await el.files[0].text()));confirmDialog('Restore backup?','This replaces workouts and drafts currently saved on this device. Export your current data first if needed.',()=>{state=candidate;assessmentTab=false;save();view='history';render()})}catch(err){alert('Could not import backup: '+err.message)}finally{el.value=''}});
function clockDuration(){return clock.mode==='rest'?clock.rest:clock.mode==='emom'?clock.minute:clock.phase==='work'?clock.work:clock.rest}
function clockLabel(){if(clock.phase==='ready')return 'Ready';if(clock.phase==='lead')return 'GET READY';if(clock.phase==='done')return 'Done';if(clock.mode==='emom')return 'EMOM · round '+clock.round+'/'+clock.rounds;return clock.phase==='work'?'WORK · '+clock.round+'/'+clock.rounds:'REST · '+clock.round+'/'+clock.rounds}
function tone(freq=850,duration=.11,when=0,shape='sine'){if(!clock.beeps)return;try{audioCtx ||=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+when;o.type=shape;o.frequency.setValueAtTime(freq,t);if(shape==='sine')o.frequency.exponentialRampToValueAtTime(freq*1.2,t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.1,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+duration+.02)}catch(e){}}
function coachWhistle(){if(!clock.beeps)return;try{audioCtx ||=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const t=audioCtx.currentTime,master=audioCtx.createGain();master.gain.setValueAtTime(.0001,t);master.gain.linearRampToValueAtTime(.13,t+.025);master.gain.setValueAtTime(.13,t+.38);master.gain.exponentialRampToValueAtTime(.0001,t+.53);master.connect(audioCtx.destination);for(const [f,v] of [[2350,.65],[2630,.35]]){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(f,t);o.frequency.linearRampToValueAtTime(f*1.045,t+.09);o.frequency.linearRampToValueAtTime(f*.99,t+.3);g.gain.value=v;o.connect(g);g.connect(master);o.start(t);o.stop(t+.55)}}catch(e){}}
function startSignal(){coachWhistle()}
function endSignal(){tone(450,.18,0);tone(380,.25,.24)}
function advanceClock(){if(clock.phase==='lead'){clock.phase=clock.mode==='rest'?'rest':'work';clock.remaining=clockDuration();startSignal();return}if(clock.mode==='rest'){clock.running=false;clock.phase='done';clock.remaining=0;endSignal();return}if(clock.mode==='emom'){if(clock.round>=clock.rounds){clock.running=false;clock.phase='done';clock.remaining=0;endSignal();return}clock.round++;clock.phase='work';clock.remaining=clock.minute;startSignal();return}if(clock.phase==='work'){clock.phase='rest';clock.remaining=clock.rest;endSignal();return}if(clock.round>=clock.rounds){clock.running=false;clock.phase='done';clock.remaining=0;endSignal();return}clock.round++;clock.phase='work';clock.remaining=clock.work;startSignal()}
function tickClock(){if(!clock.running)return;let delta=Math.max(0,Math.ceil((clock.deadline-Date.now())/1000)),steps=0;while(delta<=0&&clock.running&&steps++<100){advanceClock();if(clock.running){clock.deadline+=clock.remaining*1000;delta=Math.ceil((clock.deadline-Date.now())/1000)}}clock.remaining=Math.max(0,clock.running?delta:clock.remaining);if(clock.running&&clock.remaining<=3&&clock.remaining>=1&&clock.remaining!==clock.lastBeep){tone(700,.09);clock.lastBeep=clock.remaining}updateTimer()}
function startClock(){if(clock.running){clock.remaining=Math.max(0,Math.ceil((clock.deadline-Date.now())/1000));clock.running=false}else{if(clock.phase==='done'||clock.phase==='ready'){clock.round=1;clock.phase=clock.lead>0?'lead':clock.mode==='rest'?'rest':'work';clock.remaining=clock.phase==='lead'?clock.lead:clockDuration()}clock.running=true;clock.deadline=Date.now()+clock.remaining*1000;clock.lastBeep=0;try{audioCtx ||=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume()}catch(e){}if(clock.phase!=='lead')startSignal()}updateTimer()}
function resetClock(){clock.running=false;clock.phase='ready';clock.round=1;clock.remaining=clock.mode==='rest'?clock.rest:clock.mode==='emom'?clock.minute:clock.work;clock.lastBeep=0;updateTimer()}
function mountClock(){let dock=document.getElementById('clock-dock');if(dock)return;dock=document.createElement('aside');dock.id='clock-dock';dock.className='clock-dock';dock.innerHTML=`<div class="clock-main"><span id="clock-label">Ready</span><strong id="timer-display">01:30</strong><button id="timer-toggle" class="button">Start</button><button id="timer-reset" class="button outline">Reset</button><button id="clock-options" class="button secondary" aria-expanded="false">⚙</button></div><div id="clock-settings" hidden><label>Mode <select id="clock-mode"><option value="rest">Rest countdown</option><option value="emom">EMOM</option><option value="interval">Work / rest</option></select></label><label id="clock-work-wrap">Work (sec) <input id="clock-work" type="number" min="5" max="600" value="40"></label><label>Rest (sec) <input id="clock-rest" type="number" min="5" max="600" value="90"></label><label id="clock-minute-wrap">EMOM interval (sec) <input id="clock-minute" type="number" min="15" max="600" value="60"></label><label id="clock-rounds-wrap">Rounds <input id="clock-rounds" type="number" min="1" max="60" value="8"></label><label>Start buffer <select id="clock-lead"><option value="0">None</option><option value="5" selected>5 seconds</option><option value="10">10 seconds</option></select></label><label><input id="clock-beeps" type="checkbox" checked> Beep countdown + two beeps/whistle start + lower end tones</label><p class="muted">EMOM: each round starts on the interval; finish reps early and rest for the remainder. Work/rest alternates timed phases. Keep this screen open while timing.</p></div>`;document.body.appendChild(dock);document.body.classList.add('has-clock');clock.interval=setInterval(tickClock,200);syncClockSettings()}
function syncClockSettings(){const mode=document.getElementById('clock-mode');if(!mode)return;mode.value=clock.mode;document.getElementById('clock-work-wrap').hidden=clock.mode!=='interval';document.getElementById('clock-minute-wrap').hidden=clock.mode!=='emom';document.getElementById('clock-rounds-wrap').hidden=clock.mode==='rest'}
function updateTimer(){const n=document.getElementById('timer-display');if(!n)return;const sec=Math.max(0,clock.remaining);n.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');document.getElementById('clock-label').textContent=clockLabel();document.getElementById('timer-toggle').textContent=clock.running?'Pause':clock.phase==='ready'||clock.phase==='done'?'Start':'Resume';document.getElementById('clock-dock').classList.toggle('clock-warning',clock.running&&sec<=3)}
function network(){const el=document.getElementById('network');el.textContent=navigator.onLine?'Offline ready':'Offline';}window.addEventListener('online',network);window.addEventListener('offline',network);network();render();
